import requests
from urllib.parse import quote


def solve(inputs):
    url = 'https://jsonplaceholder.typicode.com/posts/{id}'
    params = {}
    headers = {}
    headers['Accept'] = 'application/json'
    url = url.replace('{id}', quote(str(inputs['resource_id']), safe=''))
    payload = {'body': inputs['new_body']}
    response = requests.request('PATCH', url, params=params, headers=headers, json=payload, timeout=20)
    response.raise_for_status()
